import json
import re
from collections import deque
from typing import Dict, List, Tuple, Optional


SECTION_RE = re.compile(r"^\[(.+?)\]\s*$")
CHOICE_RE = re.compile(r"^\s*\d+\.\s*(.*?)\s*->\s*(\S+)\s*$")


def _split_target(line: str) -> Tuple[str, Optional[str]]:
    if "->" in line:
        left, right = line.rsplit("->", 1)
        return left.strip(), right.strip() or None
    return line.strip(), None


def _split_speaker(text: str) -> Tuple[str, str]:
    if ":" in text:
        speaker, rest = text.split(":", 1)
        return speaker.strip(), rest.strip()
    return "", text.strip()


def parse_script(text: str) -> Dict[str, List[Dict[str, str]]]:
    sections: List[Tuple[str, List[str]]] = []
    current_id: Optional[str] = None
    current_lines: List[str] = []

    for raw in text.splitlines():
        line = raw.strip()
        if not line:
            continue
        m = SECTION_RE.match(line)
        if m:
            if current_id is not None:
                sections.append((current_id, current_lines))
            current_id = m.group(1).strip()
            current_lines = []
        else:
            if current_id is None:
                raise ValueError("Line outside of any section: %r" % line)
            current_lines.append(line)

    if current_id is not None:
        sections.append((current_id, current_lines))

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for node_id, lines in sections:
        choice_lines = []
        prompt_lines = []
        for line in lines:
            if CHOICE_RE.match(line):
                choice_lines.append(line)
            else:
                prompt_lines.append(line)

        if choice_lines:
            # Choice node
            speaker = ""
            text_val = ""
            if prompt_lines:
                # Use prompt line(s) as node text if present
                combined = []
                for pline in prompt_lines:
                    left, _ = _split_target(pline)
                    p_speaker, p_text = _split_speaker(left)
                    if not speaker and p_speaker:
                        speaker = p_speaker
                    combined.append(p_text)
                text_val = "\n".join([t for t in combined if t])
            nodes.append({
                "id": node_id,
                "text": text_val,
                "speaker": speaker,
                "type": "choice",
            })
            for cline in choice_lines:
                m = CHOICE_RE.match(cline)
                if not m:
                    raise ValueError(f"Invalid choice line: {cline}")
                choice_text = m.group(1).strip()
                target = m.group(2).strip()
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": choice_text,
                })
        else:
            # Line node
            if not lines:
                nodes.append({
                    "id": node_id,
                    "text": "",
                    "speaker": "",
                    "type": "line",
                })
                continue
            # Merge multiple prompt lines into one text block
            combined_text = []
            speaker = ""
            target: Optional[str] = None
            for idx, line in enumerate(lines):
                left, t = _split_target(line)
                p_speaker, p_text = _split_speaker(left)
                if idx == 0:
                    speaker = p_speaker
                    target = t
                else:
                    # Additional lines are appended to text, target must match if provided
                    if t and target and t != target:
                        raise ValueError(f"Conflicting targets in section {node_id}")
                    if t and not target:
                        target = t
                if p_text:
                    combined_text.append(p_text)
            text_val = "\n".join(combined_text)
            nodes.append({
                "id": node_id,
                "text": text_val,
                "speaker": speaker,
                "type": "line",
            })
            if target:
                edges.append({
                    "from": node_id,
                    "to": target,
                    "text": "",
                })

    # Build node map
    node_ids = {n["id"] for n in nodes}

    # Add implicit End node if referenced but missing
    missing_targets = {e["to"] for e in edges if e["to"] not in node_ids}
    if missing_targets:
        if missing_targets == {"End"}:
            nodes.append({
                "id": "End",
                "text": "",
                "speaker": "",
                "type": "line",
            })
            node_ids.add("End")
        else:
            raise ValueError(f"Missing target nodes: {sorted(missing_targets)}")

    # Validate reachability from first node
    if nodes:
        start_id = nodes[0]["id"]
        adj = {nid: [] for nid in node_ids}
        for e in edges:
            adj.setdefault(e["from"], []).append(e["to"])
        seen = set()
        dq = deque([start_id])
        while dq:
            cur = dq.popleft()
            if cur in seen:
                continue
            seen.add(cur)
            for nxt in adj.get(cur, []):
                if nxt not in seen:
                    dq.append(nxt)
        unreachable = sorted([nid for nid in node_ids if nid not in seen])
        if unreachable:
            raise ValueError(f"Unreachable nodes: {unreachable}")

    return {"nodes": nodes, "edges": edges}


def _dot_escape(text: str) -> str:
    return text.replace("\\", "\\\\").replace("\"", "\\\"")


def graph_to_dot(graph: Dict[str, List[Dict[str, str]]]) -> str:
    lines = ["digraph Dialogue {"]
    lines.append("  rankdir=LR;")
    for node in graph["nodes"]:
        nid = _dot_escape(node["id"])
        if node["type"] == "line":
            label = node["id"]
            if node["speaker"] or node["text"]:
                body = (f"{node['speaker']}: {node['text']}" if node["speaker"] else node["text"])
                label = f"{node['id']}\\n{body}"
            lines.append(f"  \"{nid}\" [shape=box, label=\"{_dot_escape(label)}\"];")
        else:
            label = node["id"]
            if node["text"]:
                label = f"{node['id']}\\n{node['text']}"
            lines.append(f"  \"{nid}\" [shape=diamond, label=\"{_dot_escape(label)}\"];")

    for edge in graph["edges"]:
        src = _dot_escape(edge["from"])
        dst = _dot_escape(edge["to"])
        if edge["text"]:
            lines.append(f"  \"{src}\" -> \"{dst}\" [label=\"{_dot_escape(edge['text'])}\"];" )
        else:
            lines.append(f"  \"{src}\" -> \"{dst}\";")

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()
    graph = parse_script(text)
    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, indent=2, ensure_ascii=True)
    dot = graph_to_dot(graph)
    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(dot)


if __name__ == "__main__":
    main()
